# -*- coding: utf-8 -*-
# GENERATED BY AI
"""Tests for KiCad symbol rendering (wireviz.wv_symbol)."""

from pathlib import Path

import pytest

from kiutils.symbol import SymbolLib

from wireviz.wv_symbol import render_symbol_svg, symbol_image

FIXTURE = (
    Path(__file__).parent.parent
    / "examples"
    / "resources"
    / "kicad-symbols"
    / "DemoConnector.kicad_sym"
)


@pytest.fixture
def library():
    return SymbolLib.from_file(str(FIXTURE))


@pytest.fixture
def symbol(library):
    return next(s for s in library.symbols if s.entryName == "DemoHeader_1x04")


def test_render_symbol_svg(library, symbol):
    svg, width_mm, height_mm = render_symbol_svg(symbol, library)
    assert svg.startswith("<svg")
    assert svg.endswith("</svg>")
    # one body rectangle, filled with the background color
    assert svg.count("<rect") == 1
    assert 'fill="#ffffff"' in svg
    # 4 pin leads
    assert svg.count("<line") == 4
    # pin numbers 1 to 4 and pin names
    for number in ("1", "2", "3", "4"):
        assert f">{number}</text>" in svg
    for name in ("GND", "VCC", "SDA", "SCL"):
        assert f">{name}</text>" in svg
    # the symbol is wider than tall (pins on both sides)
    assert width_mm > height_mm


def test_symbol_image():
    image = symbol_image(
        {"library": str(FIXTURE), "part": "DemoHeader_1x04", "width": 150}
    )
    assert image.src.endswith(".svg")
    assert Path(image.src).is_file()
    assert image.width == 150
    assert image.height > 0
    # height follows the symbol aspect ratio (wider than tall)
    assert image.width > image.height


def test_symbol_image_unknown_attribute():
    with pytest.raises(ValueError):
        symbol_image(
            {"library": str(FIXTURE), "part": "DemoHeader_1x04", "foo": 1}
        )


def test_symbol_image_unknown_part():
    with pytest.raises(ValueError):
        symbol_image({"library": str(FIXTURE), "part": "DoesNotExist"})
